#[derive(Debug, PartialEq, Eq)]
enum FileOpOutcome {
    Completed,
    CompletedWithWarning {
        message: String,
        completed_sources: usize,
    },
    Failed {
        message: String,
        privilege_retry: bool,
    },
}

impl FileOpOutcome {
    fn should_offer_privilege_retry(&self) -> bool {
        matches!(
            self,
            Self::Failed {
                privilege_retry: true,
                ..
            }
        )
    }
}

fn classify_file_op_result(result: Result<(), PlatformError>) -> FileOpOutcome {
    match result {
        Ok(()) => FileOpOutcome::Completed,
        Err(error @ PlatformError::CommittedCleanupPending { .. }) => {
            FileOpOutcome::CompletedWithWarning {
                message: error.to_string(),
                completed_sources: 1,
            }
        }
        Err(error @ PlatformError::PartialBatch { completed, .. }) => {
            FileOpOutcome::CompletedWithWarning {
                message: error.to_string(),
                completed_sources: completed,
            }
        }
        Err(error) => {
            let message = error.to_string();
            FileOpOutcome::Failed {
                privilege_retry: is_permission_denied_msg(&message),
                message,
            }
        }
    }
}

fn should_refresh_retained_move_activity(cmd: &FileCommand, has_warning: bool) -> bool {
    matches!(cmd, FileCommand::RecoverRetainedMove { .. })
        || (has_warning && matches!(cmd, FileCommand::Move { .. }))
}

