fn image_thumbnail_candidate(entry: &FileEntry) -> bool {
    if matches!(entry.kind, EntryKind::Directory) {
        return true;
    }
    if !matches!(entry.kind, EntryKind::File) {
        return false;
    }
    let profile = ottrin_preview::preview_profile(&entry.path);
    let is_visual = matches!(
        profile.kind(),
        PreviewKind::Image
            | PreviewKind::CameraRawMetadata
            | PreviewKind::AffinityMetadata
            | PreviewKind::SqliteMetadata
            | PreviewKind::StlMetadata
            | PreviewKind::ObjMetadata
            | PreviewKind::PlyMetadata
            | PreviewKind::ThreeMfMetadata
            | PreviewKind::Pdf
            | PreviewKind::Text
    );
    is_visual && thumbnail_supported_preview_path(&entry.path)
}

fn thumbnail_supported_preview_path(path: &Path) -> bool {
    let profile = ottrin_preview::preview_profile(path);
    profile.supports_thumbnail_visual() && !matches!(profile.kind(), PreviewKind::OfficeMetadata)
}

/// DOCX has a bounded page renderer in the preview broker. The inspector must
/// consume that image instead of leaving the broker result off-screen.
fn quick_inspector_uses_rendered_office_page(path: &Path) -> bool {
    path.extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("docx"))
}

/// Submit a ready DOCX texture and then expose its completion to accessibility.
/// Pending, missing, and failed loader results must not emit the ready marker.
#[cfg(test)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DocxInspectorPaintEvent {
    RasterSubmitted,
    ReadyMarker,
}

#[cfg(test)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DocxInspectorLayoutEvent {
    Raster {
        solid_scrollbars: bool,
        vertically_overflowing: bool,
        content_width_fits_viewport: bool,
        horizontally_overflowing: bool,
        ready_document_body_in_scroll_content: bool,
    },
    Fallback {
        solid_scrollbars: bool,
        vertically_overflowing: bool,
    },
}

#[cfg(test)]
thread_local! {
    static DOCX_INSPECTOR_PAINT_EVENTS: std::cell::RefCell<Vec<DocxInspectorPaintEvent>> = const {
        std::cell::RefCell::new(Vec::new())
    };
    static DOCX_INSPECTOR_LAYOUT_EVENTS: std::cell::RefCell<Vec<DocxInspectorLayoutEvent>> = const {
        std::cell::RefCell::new(Vec::new())
    };
}

#[cfg(test)]
fn record_docx_inspector_paint_event(event: DocxInspectorPaintEvent) {
    DOCX_INSPECTOR_PAINT_EVENTS.with(|events| events.borrow_mut().push(event));
}

#[cfg(test)]
fn take_docx_inspector_paint_events() -> Vec<DocxInspectorPaintEvent> {
    DOCX_INSPECTOR_PAINT_EVENTS.with(|events| std::mem::take(&mut *events.borrow_mut()))
}

#[cfg(test)]
fn record_docx_inspector_layout_event(event: DocxInspectorLayoutEvent) {
    DOCX_INSPECTOR_LAYOUT_EVENTS.with(|events| events.borrow_mut().push(event));
}

#[cfg(test)]
fn take_docx_inspector_layout_events() -> Vec<DocxInspectorLayoutEvent> {
    DOCX_INSPECTOR_LAYOUT_EVENTS.with(|events| std::mem::take(&mut *events.borrow_mut()))
}

fn submit_docx_raster(ui: &mut egui::Ui, image: egui::Image<'static>) -> egui::Response {
    let response = ui.add(image);
    #[cfg(test)]
    record_docx_inspector_paint_event(DocxInspectorPaintEvent::RasterSubmitted);
    response
}

fn expose_docx_raster_ready(ui: &mut egui::Ui) -> egui::Response {
    let response = ui.label("DOCX rendered page ready");
    #[cfg(test)]
    record_docx_inspector_paint_event(DocxInspectorPaintEvent::ReadyMarker);
    response
}

fn render_docx_raster_inspector_page(
    ui: &mut egui::Ui,
    texture_load_result: Option<&egui::load::TextureLoadResult>,
    visual_fit: bool,
    visual_zoom: f32,
    max_width: f32,
) -> Option<Vec2> {
    let Some(Ok(egui::load::TexturePoll::Ready { texture })) = texture_load_result else {
        return None;
    };
    let texture = *texture;
    let display_size = if visual_fit {
        texture.size * preview_render::docx_width_fit_scale(texture.size.x, max_width)
    } else {
        texture.size * visual_zoom.clamp(0.1, 8.0)
    };
    let image = egui::Image::from_texture(texture)
        .fit_to_exact_size(display_size)
        .corner_radius(8);
    let response = ui.vertical_centered(|ui| submit_docx_raster(ui, image));
    let _ = expose_docx_raster_ready(ui);
    Some(response.inner.rect.size())
}

struct SmartPanelIconButton<'a> {
    icon: &'a str,
    icon_size: f32,
    icon_color: Color32,
    active: bool,
    tooltip: &'a str,
}

fn smart_panel_icon_button(
    ui: &mut egui::Ui,
    strip_rect: Rect,
    spec: SmartPanelIconButton<'_>,
    c: &Colors,
) -> egui::Response {
    if spec.active {
        let y = ui.cursor().min.y - 2.0;
        ui.painter().rect_filled(
            Rect::from_min_size(
                egui::Pos2::new(strip_rect.min.x, y),
                Vec2::new(strip_rect.width(), 32.0),
            ),
            4.0,
            c.selected_bg,
        );
        ui.painter().vline(
            strip_rect.min.x + 1.0,
            y..=(y + 32.0),
            Stroke::new(2.0, c.accent),
        );
    }
    let resp = ui
        .add(
            egui::Button::new(
                RichText::new(spec.icon)
                    .size(spec.icon_size)
                    .color(spec.icon_color),
            )
            .frame(false)
            .min_size(Vec2::splat(30.0)),
        )
        .on_hover_text(spec.tooltip);
    if resp.hovered() {
        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
    }
    resp
}

fn smart_panel_header(ui: &mut egui::Ui, c: &Colors, icon: &str, title: &str) {
    ui.add_space(8.0);
    ui.horizontal(|ui| {
        ui.add_space(8.0);
        ui.label(RichText::new(icon).size(14.0).color(c.text_dim));
        ui.add_space(4.0);
        ui.label(RichText::new(title).color(c.text).size(14.0).strong());
    });
    ui.add_space(8.0);
    ui.painter().hline(
        ui.available_rect_before_wrap().x_range(),
        ui.cursor().min.y,
        Stroke::new(1.0, c.border),
    );
    ui.add_space(8.0);
}

fn delete_choice_row(
    ui: &mut egui::Ui,
    c: &Colors,
    choice: DeleteChoice,
    selected: bool,
) -> egui::Response {
    let (icon, label, hint, text_col) = match choice {
        DeleteChoice::MoveToTrash => (
            MI_DELETE,
            "Move to Trash",
            "Safest option. You can restore it from the system trash.",
            c.text,
        ),
        DeleteChoice::Cancel => (
            MI_CLOSE,
            "Cancel",
            "Close this dialog without deleting anything.",
            c.text_muted,
        ),
        DeleteChoice::DeletePermanently => (
            MI_DELETE,
            "Delete Permanently",
            "Bypasses the trash and cannot be undone from Ottrin.",
            c.error,
        ),
    };
    let fill = if selected { c.selected_bg } else { c.panel };
    let stroke = if selected {
        Stroke::new(1.2, c.accent)
    } else {
        Stroke::new(1.0, mix_color(c.border, c.panel_raised, 0.35))
    };
    let row_h = if selected { 48.0 } else { 38.0 };
    let (rect, response) =
        ui.allocate_exact_size(Vec2::new(ui.available_width(), row_h), Sense::click());
    response.widget_info(|| WidgetInfo::selected(WidgetType::Button, true, selected, label));

    ui.painter().rect_filled(
        rect,
        6.0,
        if response.hovered() && !selected {
            mix_color(fill, c.hover, 0.35)
        } else {
            fill
        },
    );
    ui.painter()
        .rect_stroke(rect, 6.0, stroke, egui::StrokeKind::Inside);
    ui.painter().text(
        egui::pos2(
            rect.left() + 20.0,
            rect.top() + if selected { 16.0 } else { row_h * 0.5 },
        ),
        Align2::CENTER_CENTER,
        icon,
        FontId::proportional(14.0),
        text_col,
    );
    ui.painter().text(
        egui::pos2(
            rect.left() + 42.0,
            rect.top() + if selected { 15.0 } else { row_h * 0.5 },
        ),
        Align2::LEFT_CENTER,
        label,
        FontId::proportional(12.6),
        text_col,
    );
    if selected {
        ui.painter().text(
            egui::pos2(rect.left() + 42.0, rect.top() + 31.0),
            Align2::LEFT_CENTER,
            hint,
            FontId::proportional(10.5),
            c.text_muted,
        );
    }
    if selected {
        ui.painter().vline(
            rect.left() + 2.0,
            (rect.top() + 7.0)..=(rect.bottom() - 7.0),
            Stroke::new(2.0, c.accent),
        );
    }
    response
}

