    #[test]
    fn pointer_folder_entry_updates_miller_path_and_reveals_an_empty_destination() {
        let root = std::env::temp_dir().join(format!(
            "ottrin-miller-pointer-entry-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock after epoch")
                .as_nanos(),
        ));
        let source = root.join("source");
        let destination = source.join("empty-destination");
        std::fs::create_dir_all(&destination).expect("create empty destination fixture");

        let mut app = OttrinApp::default();
        let tab_id = app.state.active_tab().id;
        app.state.active_tab_mut().view_mode = ViewMode::Miller;
        app.state.active_tab_mut().current_dir = source.clone();

        app.navigate_miller_pointer_folder(tab_id, destination.clone());

        assert_eq!(
            app.state.tab_by_id(tab_id).map(|tab| &tab.current_dir),
            Some(&destination),
            "a primary Miller folder click must make the clicked folder active"
        );
        assert!(app.tab_ui.get(&tab_id).is_some_and(|ui| {
            ui.miller_pointer_reveal
                .as_ref()
                .is_some_and(|reveal| reveal.destination() == destination)
                && ui.miller_scroll_selected
        }));
        let (columns, current_col) = app.build_miller_model(tab_id, app.miller_col_count);
        assert_eq!(columns[current_col].dir, destination);
        assert!(
            columns[current_col].entries.is_empty(),
            "the clicked empty folder must become a renderable current column"
        );

        let _ = std::fs::remove_dir_all(root);
    }

    #[test]
    fn pointer_history_reveal_consumes_the_first_rendered_destination_without_selection() {
        let root = std::env::temp_dir().join(format!(
            "ottrin-pointer-reveal-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .expect("clock after epoch")
                .as_nanos(),
        ));
        let source = root.join("source");
        let destination = root.join("destination");
        std::fs::create_dir_all(&source).expect("create source fixture");
        std::fs::create_dir_all(&destination).expect("create destination fixture");
        std::fs::write(destination.join("later-unrelated.txt"), "present")
            .expect("seed nonempty destination");

        let mut app = OttrinApp::default();
        let tab_id = app.state.active_tab().id;
        {
            let tab = app.state.tab_by_id_mut(tab_id).expect("active tab");
            tab.view_mode = ViewMode::Miller;
            tab.current_dir = source.clone();
            tab.history_back.push(destination.clone());
        }
        assert!(app.pointer_navigate(tab_id, PointerNavigation::Back));

        let render_miller_frame = |app: &mut OttrinApp| {
            let ctx = Context::default();
            let input = egui::RawInput {
                screen_rect: Some(Rect::from_min_size(
                    egui::pos2(0.0, 0.0),
                    Vec2::new(800.0, 600.0),
                )),
                ..Default::default()
            };
            let _ = ctx.run(input, |ctx| {
                egui::CentralPanel::default().show(ctx, |ui| app.render_miller(ui, tab_id));
            });
        };

        render_miller_frame(&mut app);
        assert!(
            app.tab_ui
                .get(&tab_id)
                .is_some_and(|ui| ui.miller_pointer_reveal.is_none()),
            "a nonempty destination with no restored selection must consume its reveal on its first production render"
        );

        let _ = std::fs::remove_dir_all(root);
    }

