    #[test]
    fn rubber_band_start_transfers_tandem_command_ownership_once() {
        let mut app = OttrinApp::default();
        let left_id = app.state.active_tab().id;
        let right_idx = app.state.new_tab(PathBuf::from("/tmp/rubber-band-right"));
        let right_id = app.state.tabs[right_idx].id;
        assert!(app.state.activate_tandem(0, right_idx).is_some());
        app.focus_tab(left_id);

        app.start_rubber_band_selection(right_id, egui::pos2(24.0, 32.0), egui::Modifiers::NONE);

        assert_eq!(app.state.active_tab().id, right_id);
        assert_eq!(
            app.state
                .link_view
                .as_ref()
                .expect("Tandem link")
                .active_tab_id(),
            right_id,
            "starting in the inactive Tandem pane must route subsequent keyboard commands there"
        );
        assert!(app.tab_ui[&right_id].rubber_band.is_some());

        app.start_rubber_band_selection(right_id, egui::pos2(30.0, 36.0), egui::Modifiers::NONE);
        assert_eq!(app.state.active_tab().id, right_id);
    }

    #[test]
    fn rejected_rubber_band_start_does_not_transfer_tandem_command_ownership() {
        let mut app = OttrinApp::default();
        let left_id = app.state.active_tab().id;
        let right_idx = app.state.new_tab(PathBuf::from("/tmp/rubber-band-right"));
        let right_id = app.state.tabs[right_idx].id;
        assert!(app.state.activate_tandem(0, right_idx).is_some());
        app.focus_tab(left_id);
        let pointer = egui::pos2(24.0, 32.0);
        let entry_rects = vec![(
            PathBuf::from("/tmp/entry"),
            Rect::from_center_size(pointer, egui::vec2(16.0, 16.0)),
        )];
        let ctx = Context::default();
        let input = egui::RawInput {
            screen_rect: Some(Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(100.0, 100.0),
            )),
            events: vec![
                egui::Event::PointerMoved(pointer),
                egui::Event::PointerButton {
                    pos: pointer,
                    button: egui::PointerButton::Primary,
                    pressed: true,
                    modifiers: egui::Modifiers::NONE,
                },
            ],
            ..Default::default()
        };

        let _ = ctx.run(input, |ctx| {
            egui::CentralPanel::default().show(ctx, |ui| {
                assert!(
                    app.update_rubber_band_selection(
                        ui,
                        right_id,
                        &[],
                        &entry_rects,
                        Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(100.0, 100.0)),
                    )
                    .is_none()
                );
            });
        });

        assert_eq!(app.state.active_tab().id, left_id);
        assert!(
            app.tab_ui
                .get(&right_id)
                .is_none_or(|ui_state| ui_state.rubber_band.is_none())
        );
    }

    #[test]
    fn list_rubber_band_uses_row_rectangles_for_replacement_and_modifiers() {
        let alpha = PathBuf::from("/tmp/alpha");
        let bravo = PathBuf::from("/tmp/bravo");
        let charlie = PathBuf::from("/tmp/charlie");
        let rows = vec![
            (
                alpha.clone(),
                Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(200.0, 28.0)),
            ),
            (
                bravo.clone(),
                Rect::from_min_size(egui::pos2(0.0, 28.0), egui::vec2(200.0, 28.0)),
            ),
            (
                charlie.clone(),
                Rect::from_min_size(egui::pos2(0.0, 56.0), egui::vec2(200.0, 28.0)),
            ),
        ];
        let band = Rect::from_min_max(egui::pos2(20.0, 29.0), egui::pos2(100.0, 55.0));
        let existing = HashSet::from([alpha.clone(), charlie.clone()]);

        assert_eq!(
            rubber_band_selection(&rows, band, &existing, egui::Modifiers::NONE),
            HashSet::from([bravo.clone()]),
            "an unmodified List drag replaces the previous selection with intersecting rows"
        );
        assert_eq!(
            rubber_band_selection(
                &rows,
                band,
                &existing,
                egui::Modifiers {
                    shift: true,
                    ..Default::default()
                },
            ),
            HashSet::from([alpha.clone(), bravo.clone(), charlie.clone()]),
            "Shift retains the selection baseline"
        );
        assert_eq!(
            rubber_band_selection(
                &rows,
                band,
                &existing,
                egui::Modifiers {
                    ctrl: true,
                    ..Default::default()
                },
            ),
            HashSet::from([alpha, bravo, charlie]),
            "Ctrl toggles each intersecting row against the baseline"
        );
        assert!(!rubber_band_may_start(&rows, egui::pos2(20.0, 32.0)));
        assert!(rubber_band_may_start(&rows, egui::pos2(220.0, 32.0)));
    }

