    #[test]
    fn disconnect_invalidates_clipboard_privileged_retry_and_restore_origin() {
        use std::ffi::OsString;

        let mut app = OttrinApp::default();
        let tab_id = app.state.active_tab().id;
        let root = PathBuf::from("/__ottrin_lost_root__");
        let source = root.join("report.txt");
        app.state.active_tab_mut().current_dir = root.clone();
        let location = StorageLocation {
            path: root.clone(),
            identity: "slot".to_string(),
            stable_identity: Some("volume-a".to_string()),
            kind: StorageLocationKind::Removable,
            display_name: None,
        };
        let command = FileCommand::Delete {
            targets: vec![source.clone()],
            mode: DeleteMode::Permanent,
        };
        app.clipboard = Some(Clipboard {
            generation: NEXT_CLIPBOARD_GENERATION.fetch_add(1, Ordering::Relaxed),
            sources: vec![source.clone()],
            cut: true,
            source_bindings: operation_storage_bindings(
                &FileCommand::Delete {
                    targets: vec![source.clone()],
                    mode: DeleteMode::Permanent,
                },
                std::slice::from_ref(&location),
            ),
            in_flight: false,
        });
        let retry_bindings = operation_storage_bindings(&command, std::slice::from_ref(&location));
        app.pending_privileged_retry = Some(PendingPrivilegedRetry::capture(
            command.clone(),
            Some(tab_id),
            &retry_bindings,
        ));
        app.reconcile_storage_location_availability(vec![location]);
        app.reconcile_storage_location_availability(Vec::new());

        assert!(app.clipboard.is_none());
        assert!(app.pending_privileged_retry.is_none());
        assert!(
            app.retry_file_op_with_privileges(PendingPrivilegedRetry::capture(
                command,
                Some(tab_id),
                &retry_bindings,
            ))
            .is_err()
        );

        let item = TrashItem {
            id: OsString::from("trash-id"),
            original_name: OsString::from("report.txt"),
            original_parent: root.clone(),
            trash_path: PathBuf::from("/__ottrin_trash__/report.txt"),
            original_path: source,
            deletion_date: None,
            time_deleted: 0,
            name: "report.txt".to_string(),
            kind: EntryKind::File,
            size_bytes: Some(1),
            origin_storage: None,
        };
        assert!(validate_trash_restore_provenance(&item, &[]).is_err());
    }

    #[test]
    fn unavailable_tandem_pane_does_not_isolate_its_healthy_sibling() {
        let mut app = OttrinApp::default();
        let lost_tab_id = app.state.active_tab().id;
        let healthy_tab_id = 99;
        let root = PathBuf::from("/__ottrin_volume_a__");
        app.state.active_tab_mut().current_dir = root.clone();
        app.state.tabs.push(ottrin_core::TabState::new(
            healthy_tab_id,
            PathBuf::from("/__ottrin_healthy_location__"),
        ));
        app.state.link_view = Some(ottrin_core::LinkView::new(lost_tab_id, healthy_tab_id));
        app.reconcile_storage_location_availability(vec![StorageLocation {
            path: root,
            identity: "test-volume-a".to_string(),
            stable_identity: Some("test-volume-a".to_string()),
            kind: StorageLocationKind::Removable,
            display_name: Some("Archive A".to_string()),
        }]);

        app.reconcile_storage_location_availability(Vec::new());

        assert!(app.unavailable_locations.contains_key(&lost_tab_id));
        assert!(!app.unavailable_locations.contains_key(&healthy_tab_id));
        assert_eq!(app.tandem_tab_ids(), Some((lost_tab_id, healthy_tab_id)));
    }

    #[test]
    fn superseding_search_request_cancels_the_prior_worker_token() {
        let mut slot = Some(Arc::new(AtomicBool::new(false)));
        let first = Arc::clone(slot.as_ref().expect("first request token"));

        let second = replace_search_cancellation(&mut slot);

        assert!(first.load(Ordering::Acquire));
        assert!(!second.load(Ordering::Acquire));
        assert!(Arc::ptr_eq(
            &second,
            slot.as_ref().expect("current request token")
        ));
    }

    #[test]
    fn superseding_ui_negated_search_cancels_the_live_worker_request() {
        let fixture = SearchTestFixture::new("negated-search-supersession");
        let fixture_root = fixture.root().to_path_buf();
        std::fs::write(fixture.root().join("entry.txt"), "indexed text")
            .expect("write indexed content");
        let config = SearchConfig {
            include_roots: vec![fixture.root().to_path_buf()],
            use_system_locate: false,
            ..SearchConfig::default()
        };
        let mut service =
            SearchService::new_with_store_path(config, fixture.root().join("search.db"));
        service.start();
        service
            .rebuild_index_blocking()
            .expect("build indexed generation");

        let mut app = OttrinApp::default();
        app.search_service = service;
        app.search_started = true;
        app.search_ui.query = "!needle".to_string();
        app.search_ui.content_search = true;
        app.run_search_query();
        let first = Arc::clone(
            app.search_cancellation
                .as_ref()
                .expect("first UI request has cancellation token"),
        );

        app.search_ui.query = "!other".to_string();
        app.run_search_query();
        let second = Arc::clone(
            app.search_cancellation
                .as_ref()
                .expect("second UI request has cancellation token"),
        );

        assert!(
            first.load(Ordering::Acquire),
            "the second UI request must interrupt the first negated-content worker"
        );
        let deadline = Instant::now() + Duration::from_secs(1);
        while (app.search_ui.search_inflight
            || Arc::strong_count(&first) > 1
            || Arc::strong_count(&second) > 1)
            && Instant::now() < deadline
        {
            app.poll_search_results();
            std::thread::yield_now();
        }
        app.poll_search_results();
        assert!(
            !app.search_ui.search_inflight,
            "replacement request must complete"
        );
        assert!(app.search_ui.last_error.is_none());
        assert_eq!(app.search_ui.last_executed_query, "!other");
        assert_eq!(
            Arc::strong_count(&first),
            1,
            "cancelled query task must release its fixture-backed handle before teardown"
        );
        assert_eq!(
            Arc::strong_count(&second),
            1,
            "replacement query task must release its fixture-backed handle before teardown"
        );

        drop(app);
        drop(fixture);
        assert!(
            !fixture_root.exists(),
            "fixture cleanup must run only after search service and query tasks are gone"
        );
    }

